"""Per-arm loaders (spec §1): every arm's view is generated by code from the same World (G6).

  baseline  roster.json (names) + conversation log + working-memory log, in the 5b5f635 layout
  registry  SQL rows (agents with past timestamps, keys, aliases, briefs), triggers.db rows, and the
            same conversation/working-memory history (the registry IA reads it too: runtime.py:228-234)
  rag       roster dicts for the RAG router, two variants:
              as_built  name/topic/tasks/notes only; query = message only
              enriched  + status, age, keys and the agent's last 5 conversation turns

``load_registry`` and ``world_clock`` need the *sandboxed* server package (tests/harness.py);
they refuse to run against the repo's real ``server/``.
"""

from __future__ import annotations

import contextlib
import functools
import itertools
import json
import sqlite3
import sys
from dataclasses import dataclass
from datetime import datetime, timedelta
from html import escape
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple
from unittest import mock

from .generator import entry_owners, folded_count
from .keys_pure import keybook
from .schema import Agent, Event, World

TS_FMT = "%Y-%m-%d %H:%M:%S"  # conversation log timestamps (UTC here; the app uses the user's timezone)
REPO_SERVER = Path(__file__).resolve().parent.parent / "server"


def registry_id(agent: Agent) -> str:
    return f"ea_{agent.index}"


def age_text(world: World, at: datetime) -> str:
    """Same buckets as routing_cards._age."""
    seconds = max((world.now - at).total_seconds(), 0)
    if seconds < 60:
        return "now"
    if seconds < 3600:
        return f"{int(seconds // 60)}m"
    if seconds < 86400:
        return f"{int(seconds // 3600)}h"
    return f"{int(seconds // 86400)}d"


# --------------------------------------------------------------------------- #
# conversation history (shared by baseline and registry; agent_message format per code version)
# --------------------------------------------------------------------------- #
def _encode(payload: str) -> str:
    normalized = payload.replace("\r\n", "\n").replace("\r", "\n")
    return escape(normalized.replace("\n", "\\n"), quote=False)


def _line(tag: str, payload: str, ts: Optional[str] = None) -> str:
    if ts:
        return f'<{tag} timestamp="{ts}">{_encode(payload)}</{tag}>\n'
    return f"<{tag}>{_encode(payload)}</{tag}>\n"


def conversation_entries(world: World, arm: str) -> List[Tuple[str, str, str]]:
    """(tag, timestamp, payload) in order. ``arm`` picks the agent_message prefix:
    baseline (5b5f635 batch_manager.py:177) ``[SUCCESS] <name>: <text>``;
    registry (main batch_manager.py:198-199) ``[SUCCESS] ea_k (<name>): <text>``."""
    by_ref = {a.ref: a for a in world.agents}
    out: List[Tuple[str, str, str]] = []
    for ev in world.events:
        ts = ev.at.strftime(TS_FMT)
        out.append(("user_message", ts, ev.user_message))
        if ev.kind == "step":
            agent = by_ref[ev.agent_ref]
            who = agent.name if arm == "baseline" else f"{registry_id(agent)} ({agent.name})"
            out.append(("agent_message", ts, f"[SUCCESS] {who}: {ev.ea_text}"))
        out.append(("poke_reply", ts, ev.reply))
    return out


def summary_text(world: World) -> str:
    """Working-memory summary of the folded entries.

    TODO(D-005 §1/§4): the real summary is written by the summarizer model. This template is a
    placeholder: one line per folded workstream topic, never an agent name (the "dropped link")."""
    owners = entry_owners(world.events)
    cut = folded_count(len(owners))
    seen: List[str] = []
    for ws_id in owners[:cut]:
        if ws_id and ws_id not in seen:
            seen.append(ws_id)
    if not seen:
        return ""
    lines = ["Earlier in the conversation:"] + [f"- The user asked for help with {world.ws(w).topic}." for w in seen]
    return "\n".join(lines)


def write_conversation(world: World, conv_dir: Path, arm: str) -> Dict[str, Any]:
    entries = conversation_entries(world, arm)
    cut = folded_count(len(entries))
    conv_dir.mkdir(parents=True, exist_ok=True)
    (conv_dir / "poke_conversation.log").write_text("".join(_line(t, p, ts) for t, ts, p in entries), encoding="utf-8")
    last_at = entries[cut - 1][1] if cut else None
    meta = json.dumps({"last_index": cut - 1, "updated_at": (world.now.isoformat() if cut else None)})
    wm = [_line("summary_info", meta), _line("conversation_summary", summary_text(world))]
    wm += [_line(t, p, ts) for t, ts, p in entries[cut:]]
    (conv_dir / "poke_working_memory.log").write_text("".join(wm), encoding="utf-8")
    return {"entries": len(entries), "folded": cut, "last_folded_at": last_at}


# --------------------------------------------------------------------------- #
# baseline (5b5f635): roster.json names + conversation/working memory
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class BaselineView:
    data_dir: Path
    roster: Tuple[str, ...]                    # roster.json, creation order, exact-name dedup
    agents_by_name: Dict[str, Tuple[str, ...]]  # name -> agent refs (same name = one baseline agent)


def load_baseline(world: World, data_dir: Path) -> BaselineView:
    names: List[str] = []
    by_name: Dict[str, List[str]] = {}
    for a in world.agents:  # AgentRoster.add_agent keeps the first occurrence of each exact name
        if a.name not in names:
            names.append(a.name)
        by_name.setdefault(a.name, []).append(a.ref)
    exec_dir = data_dir / "execution_agents"
    exec_dir.mkdir(parents=True, exist_ok=True)
    (exec_dir / "roster.json").write_text(json.dumps(names, indent=2), encoding="utf-8")
    write_conversation(world, data_dir / "conversation", "baseline")
    return BaselineView(data_dir, tuple(names), {k: tuple(v) for k, v in by_name.items()})


# --------------------------------------------------------------------------- #
# RAG (worktree-rag-router): roster dicts
# --------------------------------------------------------------------------- #
RAG_ENV = {"OPENPOKE_RAG_EMBEDDER": "openrouter"}  # forced; never auto/sentence-transformers/hash
RAG_FORBIDDEN_EMBEDDERS = ("hash-384",)             # rag_router.HashEmbedder.name (EMBED_DIM = 384)
RAG_TIERS = ("A",)                                   # RAG runs in Tier A only
RAG_VARIANTS = ("as_built", "enriched")
RAG_LAST_TURNS = 5


class RagEmbedderAbort(RuntimeError):
    """The RAG router fell back to the hash embedder; the run is invalid."""


def check_rag_debug(debug: Dict[str, Any], log: Optional[List[str]] = None) -> str:
    """Record ``debug["embedder"]`` for this turn; abort if it is the hash fallback."""
    name = str(debug.get("embedder", ""))
    if log is not None:
        log.append(name)
    if not name or name in RAG_FORBIDDEN_EMBEDDERS or name.startswith("hash-"):
        raise RagEmbedderAbort(f"RAG embedder is {name!r}; aborting (hash fallback is not allowed)")
    return name


def _open_items(world: World, agent: Agent, book) -> List[str]:
    """Same derivation as routing_cards._open_items: unsent drafts and still-active triggers."""
    active_triggers = {str(w.trigger) for w in world.workstreams
                       if w.trigger is not None and w.trigger_active and w.ws_id in agent.ws_ids}
    items: List[str] = []
    for kind, value in sorted(book.open_keys(agent.ref)):
        if kind == "draft":
            items.append(f"draft {value}")
        elif kind == "trigger" and value in active_triggers:
            items.append(f"trigger t_{value}")
    return items


def _turns(world: World, agent: Agent) -> List[Event]:
    return [e for e in world.events if e.kind == "step" and e.agent_ref == agent.ref]


def rag_roster(world: World, variant: str) -> List[Dict[str, Any]]:
    if variant not in RAG_VARIANTS:
        raise ValueError(variant)
    book = keybook(world)
    out: List[Dict[str, Any]] = []
    for a in world.agents:  # every agent, done included
        turns = _turns(world, a)
        doc: Dict[str, Any] = {
            "agent_id": registry_id(a),
            "name": a.name,
            "topic": a.brief,
            "active_tasks": _open_items(world, a, book),
            "past_action_notes": [e.ea_text for e in turns],
        }
        if variant == "enriched":
            keys = ", ".join(f"{t}:{v}" for t, v in sorted(book.owned[a.ref]))
            doc["topic"] = (f"{a.brief} | status: {a.status} | last active: {age_text(world, a.last_active_at)} ago"
                            f" | keys: {keys or 'none'}")
            doc["past_action_notes"] = [f"user: {e.user_message} / agent: {e.ea_text}"
                                        for e in turns[-RAG_LAST_TURNS:]]
        out.append(doc)
    return out


def rag_query(message: str, variant: str) -> str:
    """Both variants send the message only (the router takes no conversation input)."""
    if variant not in RAG_VARIANTS:
        raise ValueError(variant)
    return message


# --------------------------------------------------------------------------- #
# registry (main): SQL replay through the real key extraction and report parser
# --------------------------------------------------------------------------- #
def _require_sandbox() -> None:
    mod = sys.modules.get("server")
    if mod is None:
        raise RuntimeError("import tests/harness.py first (sandboxed server copy)")
    path = Path(mod.__file__).resolve()
    if REPO_SERVER in path.parents or path.parent == REPO_SERVER:
        raise RuntimeError(f"refusing to load a world into the real server package at {path}")


@dataclass(frozen=True)
class RegistryView:
    id_of: Dict[str, str]     # agent ref -> ea_k
    ref_of: Dict[str, str]    # ea_k -> agent ref
    conversation: Dict[str, Any]


def load_registry(world: World, registry, trigger_store, conv_dir: Path) -> RegistryView:
    """Seed an *empty* sandbox registry + trigger store with this world's history."""
    _require_sandbox()
    from server.agents.execution_agent.report import parse_report
    from server.services.execution import keys as K
    from server.services.execution.agent_registry import KeyRef, normalize_key

    if registry.count() != 0:
        raise RuntimeError("registry must be empty")
    id_of: Dict[str, str] = {}
    with contextlib.closing(sqlite3.connect(registry._db_path)) as conn, conn:
        for a in world.agents:
            seq = conn.execute("INSERT INTO agent_id_seq DEFAULT VALUES").lastrowid
            agent_id = f"ea_{seq}"
            if agent_id != registry_id(a):
                raise RuntimeError(f"registry issued {agent_id} for {a.ref}; expected {registry_id(a)}")
            id_of[a.ref] = agent_id
            conn.execute(
                "INSERT INTO agents (agent_id, label, brief, status, created_at, last_active_at)"
                " VALUES (?, ?, '', 'active', ?, ?)",
                (agent_id, a.name, a.created_at.isoformat(), a.created_at.isoformat()),
            )
        aliases = set()
        for ev in world.events:
            if ev.kind != "step":
                continue
            agent_id = id_of[ev.agent_ref]
            at = ev.at.isoformat()
            for tc in ev.tool_calls:
                for key in K.extract_from_tool_call(tc.name, dict(tc.args), dict(tc.result)):
                    k = normalize_key(key)
                    conn.execute(
                        "INSERT OR IGNORE INTO agent_keys (agent_id, key_type, key_value, created_at) VALUES (?, ?, ?, ?)",
                        (agent_id, k.type, k.value, at),
                    )
                for key in K.extract_closed_from_tool_call(tc.name, dict(tc.args), dict(tc.result)):
                    k = normalize_key(key)
                    conn.execute(
                        "UPDATE agent_keys SET closed_at = ? WHERE key_type = ? AND key_value = ? AND closed_at IS NULL",
                        (at, k.type, k.value),
                    )
                aliases |= K.extract_aliases(tc.name, dict(tc.args), dict(tc.result))
                if tc.name == "createTrigger":
                    _seed_trigger(trigger_store, world, ev, tc, agent_id)
            parsed = parse_report(f'{ev.ea_text}\n<report status="{ev.report_status}">{ev.report_brief}</report>')
            if parsed.report is None:
                raise RuntimeError(f"world report rejected by parse_report: {parsed.problem}")
            conn.execute("UPDATE agents SET brief = ?, status = ?, last_active_at = ? WHERE agent_id = ?",
                         (parsed.report.brief, parsed.report.status, at, agent_id))
    for address, name in sorted(aliases):
        registry.add_alias(address, name)
    conv = write_conversation(world, conv_dir, "registry")
    return RegistryView(id_of, {v: k for k, v in id_of.items()}, conv)


def _seed_trigger(trigger_store, world: World, ev: Event, tc, agent_id: str) -> None:
    ws = world.ws(ev.ws_id)
    trigger_id = int(tc.result["trigger_id"])
    status = "active" if ws.trigger_active else "completed"
    with contextlib.closing(sqlite3.connect(trigger_store._db_path)) as conn, conn:
        conn.execute(
            "INSERT INTO triggers (id, agent_id, payload, start_time, next_trigger, recurrence_rule, timezone,"
            " status, last_error, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)",
            (trigger_id, agent_id, str(tc.args.get("payload", "")), ev.at.isoformat(), None, None, "UTC",
             status, ev.at.isoformat(), ev.at.isoformat()),
        )


@contextlib.contextmanager
def world_clock(world: World, registry):
    """Patch the registry clock and pass the world's ``now`` to card rendering (spec §1)."""
    _require_sandbox()
    from server.agents.interaction_agent import agent as ia_agent
    from server.agents.interaction_agent import tools as ia_tools

    tick = itertools.count(1)  # strictly increasing, like AgentRegistry._now
    with contextlib.ExitStack() as st:
        st.enter_context(mock.patch.object(registry, "_now",
                                           lambda: world.now + timedelta(microseconds=next(tick))))
        st.enter_context(mock.patch.object(ia_agent, "render_block",
                                           functools.partial(ia_agent.render_block, now=world.now)))
        st.enter_context(mock.patch.object(ia_tools, "render_card",
                                           functools.partial(ia_tools.render_card, now=world.now)))
        yield
